package com.cat.client

import android.content.Context
import org.json.JSONObject
import java.math.BigInteger
import java.net.HttpURLConnection
import java.net.URL
import java.security.SecureRandom
import java.text.SimpleDateFormat
import java.util.Base64
import java.util.Date
import java.util.Locale
import java.util.TimeZone

/**
 * Real Cloudflare WARP registration for `awg://auto@…` / `wireguard://auto@…` configs.
 *
 * Earlier builds put a fixed placeholder private key (`YAutoGenerated…=`) into those configs.
 * That key was never registered with Cloudflare, so the WireGuard handshake could never succeed
 * — every built-in "AWG / WARP" entry silently failed. This object generates a real X25519 key
 * pair (pure Kotlin, works on every Android version), registers it with the public WARP API
 * (the same flow wgcf / Aether use), caches the account, and swaps the placeholder for it right
 * before the core starts.
 */
object WarpRegistration {
    const val PLACEHOLDER_PRIVATE_KEY = "YAutoGeneratedClientPrivateKeyForWarpTunnel="
    const val WARP_PEER_PUBLIC_KEY = "bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo="
    private const val PREFS = "cat_client_warp_account"
    private const val KEY_JSON = "account"
    private val API_URLS = listOf(
        "https://api.cloudflareclient.com/v0a2158/reg",
        "https://api.cloudflareclient.com/v0a1922/reg",
    )

    data class Account(
        val privateKey: String,
        val publicKey: String,
        val peerPublicKey: String,
        val ipv4: String,
        val ipv6: String?,
        val reserved: List<Int>?,
        val accountId: String,
    ) {
        fun toJson(): JSONObject = JSONObject()
            .put("privateKey", privateKey)
            .put("publicKey", publicKey)
            .put("peerPublicKey", peerPublicKey)
            .put("ipv4", ipv4)
            .put("ipv6", ipv6.orEmpty())
            .put("reserved", reserved?.joinToString(",").orEmpty())
            .put("id", accountId)

        companion object {
            fun fromJson(o: JSONObject): Account? {
                val priv = o.optString("privateKey").takeIf { it.length >= 43 } ?: return null
                return Account(
                    privateKey = priv,
                    publicKey = o.optString("publicKey"),
                    peerPublicKey = o.optString("peerPublicKey").ifBlank { WARP_PEER_PUBLIC_KEY },
                    ipv4 = o.optString("ipv4").ifBlank { "172.16.0.2" },
                    ipv6 = o.optString("ipv6").takeIf(String::isNotBlank),
                    reserved = o.optString("reserved").split(',').mapNotNull { it.trim().toIntOrNull() }
                        .takeIf { it.size == 3 },
                    accountId = o.optString("id"),
                )
            }
        }
    }

    fun cached(context: Context): Account? {
        val raw = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString(KEY_JSON, null) ?: return null
        return runCatching { Account.fromJson(JSONObject(raw)) }.getOrNull()
    }

    fun forget(context: Context) {
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().remove(KEY_JSON).apply()
    }

    /** Returns the cached account or registers a new one. Blocking network call. */
    fun ensureAccount(context: Context): Account? {
        cached(context)?.let { return it }
        val account = register() ?: return null
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit()
            .putString(KEY_JSON, account.toJson().toString()).apply()
        return account
    }

    fun register(random: SecureRandom = SecureRandom()): Account? {
        val privateBytes = ByteArray(32).also(random::nextBytes)
        clamp(privateBytes)
        val publicBytes = publicKeyOf(privateBytes)
        val privateB64 = Base64.getEncoder().encodeToString(privateBytes)
        val publicB64 = Base64.getEncoder().encodeToString(publicBytes)
        val tos = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.US)
            .apply { timeZone = TimeZone.getTimeZone("UTC") }
            .format(Date())
        val body = JSONObject()
            .put("key", publicB64)
            .put("install_id", "")
            .put("fcm_token", "")
            .put("tos", tos)
            .put("model", "PC")
            .put("serial_number", "")
            .put("locale", "en_US")
            .toString()
        for (endpoint in API_URLS) {
            val response = runCatching { post(endpoint, body) }.getOrNull() ?: continue
            parseRegistration(response, privateB64, publicB64)?.let { return it }
        }
        return null
    }

    internal fun parseRegistration(json: String, privateB64: String, publicB64: String): Account? = runCatching {
        val root = JSONObject(json).let { it.optJSONObject("result") ?: it }
        val config = root.optJSONObject("config") ?: return null
        val peer = config.optJSONArray("peers")?.optJSONObject(0)
        val addresses = config.optJSONObject("interface")?.optJSONObject("addresses")
        val reserved = config.optString("client_id").takeIf(String::isNotBlank)?.let { clientId ->
            runCatching { Base64.getDecoder().decode(clientId) }.getOrNull()
                ?.takeIf { it.size >= 3 }
                ?.take(3)
                ?.map { it.toInt() and 0xFF }
        }
        Account(
            privateKey = privateB64,
            publicKey = publicB64,
            peerPublicKey = peer?.optString("public_key")?.takeIf(String::isNotBlank) ?: WARP_PEER_PUBLIC_KEY,
            ipv4 = addresses?.optString("v4")?.takeIf(String::isNotBlank) ?: "172.16.0.2",
            ipv6 = addresses?.optString("v6")?.takeIf(String::isNotBlank),
            reserved = reserved,
            accountId = root.optString("id"),
        )
    }.getOrNull()

    /**
     * Replaces the placeholder key in every WireGuard block of [yaml] with the registered account
     * and injects its IPv6 address / reserved bytes when the block does not define them.
     */
    fun patchYaml(yaml: String, account: Account): String {
        if (!yaml.contains(PLACEHOLDER_PRIVATE_KEY)) return yaml
        fun indentOf(line: String) = line.takeWhile { it == ' ' }.length
        val lines = yaml.lines()
        val out = ArrayList<String>(lines.size + 8)
        var idx = 0
        while (idx < lines.size) {
            val line = lines[idx]
            if (!line.trimStart().startsWith("- ")) {
                out += line.replace(PLACEHOLDER_PRIVATE_KEY, account.privateKey)
                idx++
                continue
            }
            val itemIndent = indentOf(line)
            var end = idx + 1
            while (end < lines.size && lines[end].isNotBlank() && indentOf(lines[end]) > itemIndent) end++
            val block = lines.subList(idx, end)
            val keyLine = block.firstOrNull { it.contains(PLACEHOLDER_PRIVATE_KEY) }
            if (keyLine == null) {
                out += block
            } else {
                val keys = block.map { it.trim().removePrefix("- ").substringBefore(':').trim() }.toSet()
                val childIndent = " ".repeat(
                    if (keyLine.trimStart().startsWith("- ")) itemIndent + 2 else indentOf(keyLine),
                )
                block.forEach { out += it.replace(PLACEHOLDER_PRIVATE_KEY, account.privateKey) }
                if (account.ipv6 != null && "ipv6" !in keys) out += "${childIndent}ipv6: ${account.ipv6}"
                if (account.reserved != null && "reserved" !in keys) {
                    out += "${childIndent}reserved: [${account.reserved.joinToString(", ")}]"
                }
            }
            idx = end
        }
        return out.joinToString("\n")
    }

    private fun post(url: String, body: String): String? {
        val connection = (URL(url).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            connectTimeout = 10_000
            readTimeout = 15_000
            doOutput = true
            setRequestProperty("Content-Type", "application/json; charset=UTF-8")
            setRequestProperty("User-Agent", "okhttp/3.12.1")
            setRequestProperty("CF-Client-Version", "a-6.30-3596")
        }
        return try {
            connection.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
            if (connection.responseCode !in 200..299) return null
            connection.inputStream.bufferedReader().use { it.readText() }
        } finally {
            connection.disconnect()
        }
    }

    // ---- X25519 (RFC 7748) -------------------------------------------------------------------

    private val P: BigInteger = BigInteger.ONE.shiftLeft(255).subtract(BigInteger.valueOf(19))
    private val A24: BigInteger = BigInteger.valueOf(121665)
    private val BASE_POINT = ByteArray(32).also { it[0] = 9 }

    fun clamp(scalar: ByteArray) {
        scalar[0] = (scalar[0].toInt() and 248).toByte()
        scalar[31] = ((scalar[31].toInt() and 127) or 64).toByte()
    }

    fun publicKeyOf(privateKey: ByteArray): ByteArray = x25519(privateKey, BASE_POINT)

    fun x25519(scalar: ByteArray, uCoordinate: ByteArray): ByteArray {
        require(scalar.size == 32 && uCoordinate.size == 32)
        val k = scalar.copyOf().also(::clamp)
        val kInt = BigInteger(1, k.reversedArray())
        val u = uCoordinate.copyOf().also { it[31] = (it[31].toInt() and 127).toByte() }
        val x1 = BigInteger(1, u.reversedArray()).mod(P)
        var x2 = BigInteger.ONE
        var z2 = BigInteger.ZERO
        var x3 = x1
        var z3 = BigInteger.ONE
        var swap = 0
        for (t in 254 downTo 0) {
            val kt = if (kInt.testBit(t)) 1 else 0
            swap = swap xor kt
            if (swap == 1) {
                x2 = x3.also { x3 = x2 }
                z2 = z3.also { z3 = z2 }
            }
            swap = kt
            val a = x2.add(z2).mod(P)
            val aa = a.multiply(a).mod(P)
            val b = x2.subtract(z2).mod(P)
            val bb = b.multiply(b).mod(P)
            val e = aa.subtract(bb).mod(P)
            val c = x3.add(z3).mod(P)
            val d = x3.subtract(z3).mod(P)
            val da = d.multiply(a).mod(P)
            val cb = c.multiply(b).mod(P)
            val sum = da.add(cb).mod(P)
            val diff = da.subtract(cb).mod(P)
            x3 = sum.multiply(sum).mod(P)
            z3 = x1.multiply(diff.multiply(diff).mod(P)).mod(P)
            x2 = aa.multiply(bb).mod(P)
            z2 = e.multiply(aa.add(A24.multiply(e)).mod(P)).mod(P)
        }
        if (swap == 1) {
            x2 = x3.also { x3 = x2 }
            z2 = z3.also { z3 = z2 }
        }
        val result = x2.multiply(z2.modPow(P.subtract(BigInteger.valueOf(2)), P)).mod(P)
        val be = result.toByteArray()
        val out = ByteArray(32)
        // big-endian (possibly with sign byte) → 32-byte little-endian
        for (idx in 0 until 32) {
            val src = be.size - 1 - idx
            out[idx] = if (src >= 0) be[src] else 0
        }
        return out
    }
}
